type FollowUpState = "vencido" | "hoje" | "futuro" | "nenhum";
function followUpState(lead: Lead): FollowUpState { if (!lead.nextActionAt) return "nenhum"; if (isDue(lead)) return "vencido"; return isToday(lead) ? "hoje" : "futuro"; }
function dueLabel(lead: Lead) { if (!lead.nextActionAt) return "sem follow-up"; const midnight = (d: Date) => { d.setHours(0, 0, 0, 0); return d.getTime(); }; const diff = Math.round((midnight(new Date(lead.nextActionAt)) - midnight(new Date())) / 86400000); return diff < 0 ? `venceu há ${Math.abs(diff)}d` : diff === 0 ? "hoje" : diff === 1 ? "amanhã" : `em ${diff}d`; }
function formatDateTime(value: string) { return new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" }).format(new Date(value)); }
function daysFromNow(days: number) { const date = new Date(); date.setHours(9, 0, 0, 0); date.setDate(date.getDate() + days); return date.toISOString(); }
function statusTone(status: LeadStatus) { return status === "Ganho" ? "won" : status === "Perdido" || status === "Não agora" ? "lost" : stageGroups.ativos.includes(status) ? "warm" : "cold"; }
function toDateInputValue(value?: string) { if (!value) return ""; const d = new Date(value); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`; }
const serviceBySegment: Record<Segment, string> = { Serviços: "Agenda + ordem de serviço + contratos", Imobiliárias: "Pipeline + follow-up + agenda", Distribuidoras: "Catálogo B2B + orçamento + pedidos", Outros: "Diagnóstico comercial inicial" };
