function normalizePhone(phone: string) { const digits = phone.replace(/\D/g, ""); return digits.startsWith("55") ? digits : `55${digits}`; }
function normalize(value: string) { return value.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, " ").trim(); }
/**
 * Reconstrói as camadas derivadas a partir dos fatos guardados no lead (topo ou registro de
 * pesquisa), para que ficha, lista, score e mensagem nunca discordem entre si depois de um
 * reload. É puro e só preenche vazio: quem já tem análise persistida mantém a sua.
 */
function withStoredEvidence(lead: Lead): Lead {
  const facts = lead.facts ?? lead.research?.facts;
  if (!facts) return lead;
  const { patch } = leadPatchFromResearch(lead, facts, lead.research?.researchedAt ?? lead.research?.lastResearchAt);
  const merged = { ...lead, ...patch, facts } as Lead;
  const interpretation = lead.interpretation ?? interpretLead(merged, facts);
  if (lead.scoreDeltas) return { ...merged, interpretation };
  // o estado "antes" é o próprio lead cru: foi ele que a pesquisa completou
  const scored = evidenceScore(merged, facts, lead);
  return { ...merged, interpretation, score: scored.score, scoreBase: scored.base, scoreDeltas: scored.deltas };
}

function approachesFor(lead: Lead, objective?: Objective): GeneratedApproach[] {
  return buildApproaches(contextFromLead({ ...lead, objective: objective ?? lead.objective ?? objectiveFor({ opportunity: lead.opportunity, service: lead.service, pain: lead.pain, segment: lead.segment, facts: lead.facts }) }));
}
/** Texto a enviar: o rascunho editado pelo vendedor tem precedência sobre o gerado. */
function outboundText(lead: Lead, style?: "Direta" | "Consultiva" | "Natural") {
  return pickApproachText(approachesFor(lead), style ?? lead.approachStyle ?? "Natural", lead.approachDraft?.[style ?? lead.approachStyle ?? "Natural"]);
}
function buildMessage(lead: Lead) { return outboundText(lead); }
function isDue(lead: Lead) { return Boolean(lead.nextActionAt && new Date(lead.nextActionAt).getTime() <= Date.now()); }
function isToday(lead: Lead) { if (!lead.nextActionAt) return false; const d = new Date(lead.nextActionAt); const now = new Date(); return d.toDateString() === now.toDateString(); }
/** De onde vem o número do card: evidência da pesquisa ou só o cadastro. */
function scoreEvidenceTag(lead: Lead) {
  if (!lead.facts) return " · só o cadastro";
  if (!lead.facts.fetchOk) return " · fonte não respondeu";
  if (!lead.scoreDeltas) return " · lido, score do cadastro";
  return lead.scoreDeltas.length ? ` · com evidência (${lead.scoreBase ?? lead.score}→${lead.score})` : " · lido, sem mudança no score";
}
function scoreEvidenceHint(lead: Lead) {
  if (!lead.facts?.fetchOk) return lead.facts ? "A leitura da fonte falhou — o score não recebeu evidência externa." : "Score heurístico do cadastro. Pesquisar o site traz evidência (e os motivos).";
  const lines = (lead.scoreDeltas ?? []).map((d) => `${d.delta > 0 ? "+" : ""}${d.delta} ${d.label}`);
  return lines.length ? `base ${lead.scoreBase ?? lead.score} → ${lead.score}\n${lines.join("\n")}` : "A página foi lida e não alterou o score.";
}

function priorityReason(lead: Lead) { if (isDue(lead)) return "Follow-up vencido: precisa de atenção agora."; const status = lead.status; if (status === "Respondeu") return "Há uma resposta pendente para tratar."; if (status === "Reunião") return "Reunião marcada: preparar o próximo passo."; if (lead.score >= 85 && lead.phone) return "Alta aderência, contato disponível e oportunidade comercial clara."; return "Prioridade baseada no score e na aderência do segmento."; }
function buildVariants(lead: Lead, objective?: Objective): Record<"Direta" | "Consultiva" | "Natural", string> {
  const map = Object.fromEntries(approachesFor(lead, objective).map((item) => [item.style, item.text]));
  return { Direta: map.Direta, Consultiva: map.Consultiva, Natural: map.Natural };
}

function parseCsv(text: string): { rows: string[][]; separator: string } { const separator = (text.split(/\r?\n/)[0].match(/;/g)?.length ?? 0) >= (text.split(/\r?\n/)[0].match(/,/g)?.length ?? 0) ? ";" : ","; const rows: string[][] = []; for (const line of text.split(/\r?\n/).filter(Boolean)) { const cells: string[] = []; let cell = "", quoted = false; for (let i = 0; i < line.length; i++) { const c = line[i]; if (c === '"') quoted = !quoted; else if (c === separator && !quoted) { cells.push(cell.trim()); cell = ""; } else cell += c; } cells.push(cell.trim()); rows.push(cells); } return { rows, separator }; }

