  useEffect(() => { localStorage.setItem("prospecta-leads-v2", JSON.stringify(allLeads)); }, [allLeads]); useEffect(() => { localStorage.setItem("prospecta-statuses-v2", JSON.stringify(statuses)); }, [statuses]);
  const enriched = useMemo(() => allLeads.map((raw) => { const lead = withStoredEvidence(raw); return { ...lead, status: statuses[lead.id] || "Novo", intelligence: raw.intelligence ?? analyzeLead({ ...lead, facts: lead.facts }), service: lead.service ?? serviceBySegment[lead.segment] }; }), [allLeads, statuses]);
  const filtered = useMemo(() => { const q = normalize(query); const rows = enriched.filter((lead) => { const fu = followUpState(lead); return (segment === "Todos" || lead.segment === segment) && (priority === "Todas" || lead.priority === priority) && (statusFilter === "Todos" || lead.status === statusFilter) && (followUpFilter === "Todos" || (followUpFilter === "nenhum" ? fu === "nenhum" : followUpFilter === "vencido" ? fu === "vencido" : fu === "hoje")) && (!q || normalize(`${lead.name} ${lead.segment} ${lead.location} ${lead.pain} ${lead.opportunity} ${lead.service ?? ""}`).includes(q)); }); const rank = (lead: Lead) => { const order = statusOptions.indexOf(lead.status ?? "Novo"); return order < 0 ? 0 : order; }; if (sortBy === "nome") return [...rows].sort((a, b) => a.name.localeCompare(b.name, "pt-BR")); if (sortBy === "followup") return [...rows].sort((a, b) => (b.nextActionAt ? 1 : 0) - (a.nextActionAt ? 1 : 0) || (a.nextActionAt || "").localeCompare(b.nextActionAt || "") || b.score - a.score); return [...rows].sort((a, b) => Number(isDue(b)) - Number(isDue(a)) || b.score - a.score || rank(b) - rank(a)); }, [enriched, query, segment, priority, statusFilter, followUpFilter, sortBy]);
